    /* Distinguish from the .comment class used for code formatting without extra specificity */
    &:where(.comments &) {
      display: flex;
      margin-inline: auto;
      max-inline-size: var(--comment-max);
      position: relative;
    }

    .comment-by-system & {
      --comment-padding-block: var(--block-space-half);

      text-align: center;

      &::before {
        /* Make up space for lack of avatar */
        content: "";
