        const pill = document.querySelector(#{root.to_json} + " .reaction")
        const cs = getComputedStyle(pill)
        let out = [`pill padding=${cs.padding} gap=${cs.gap} margin=${cs.margin} width=${cs.width}`]
        for (const child of pill.children) {
          const r = child.getBoundingClientRect(), c = getComputedStyle(child)
          out.push(`  <${child.tagName.toLowerCase()} class="${child.className}"> x=${r.left.toFixed(1)} w=${r.width.toFixed(1)} h=${r.height.toFixed(1)} display=${c.display} margin=${c.margin} padding=${c.padding} position=${c.position}`)
        }
        const fig = pill.querySelector("figure")
        const fcs = getComputedStyle(fig)
        out.push(`figure margin=${fcs.margin} padding=${fcs.padding} inline-size=${fcs.inlineSize}`)
        return out.join("\\n")
      })()
    JS
  end
end
